public class PostgresOrderRepository implements OrderRepository {
    private final DataSource dataSource;

    public PostgresOrderRepository(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public void save(Order order) {
        String sql = "insert into orders (id, status, total) values (?, ?, ?) "
            + "on conflict (id) do update set status = ?, total = ?";
        try (Connection conn = dataSource.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, order.getId());
            stmt.setString(2, order.getStatus());
            stmt.setBigDecimal(3, order.getTotal());
            stmt.setString(4, order.getStatus());
            stmt.setBigDecimal(5, order.getTotal());
            stmt.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    public Optional<Order> findById(String orderId) {
